import pandas as pd

def concat_dataframes(dfs):
    result = pd.concat(dfs, ignore_index=True)
    for col in result.columns:
        if result[col].dtype == 'object':
            try:
                result[col] = pd.to_numeric(result[col])
            except ValueError:
                pass
    return result
